#!/usr/bin/env bash
# 在 binlog 里找误操作：打印匹配语句所在的文件、位置、时间和 GTID，用来确定恢复截止点。
#
# 用法（lab-dev 下载好 binlog 后，或直接在 lab-db1 上）：
#   bash mysql/find-binlog-event.sh /data/pitr/binlog 'DROP TABLE'
#   bash mysql/find-binlog-event.sh /data/pitr/binlog 'DELETE FROM `mall`.`orders`'
#
# 输出示例：
#   binlog.000015  at 4521  2026-11-24 15:31:07  GTID 3e11fa47-...:1234  DROP TABLE `orders` /* generated by server */
# 拿到 GTID 后：EXCLUDE_GTIDS=<GTID> bash mysql/mysql-pitr-restore.sh
# 拿到时间后：  STOP_DATETIME='2026-11-24 15:31:07' bash mysql/mysql-pitr-restore.sh
set -euo pipefail

dir="${1:?用法: $0 <binlog目录> <要找的语句片段>}"
pattern="${2:?用法: $0 <binlog目录> <要找的语句片段>}"
MYSQLBINLOG="${MYSQLBINLOG:-mysqlbinlog}"

found=0
# 通配符展开本身是按文件名排序的，binlog.000012 这种格式排序结果就是时间顺序
for path in "$dir"/*.[0-9][0-9][0-9][0-9][0-9][0-9]; do
  [[ -f "$path" ]] || continue
  f="${path##*/}"
  # -vv 把行格式事件解码成伪 SQL（### DELETE FROM ...），这样 DELETE / UPDATE 也能搜到
  # --no-defaults：不读 my.cnf。[client] 里写了 default-character-set 之类的选项时，mysqlbinlog 会直接报错退出
  out="$("$MYSQLBINLOG" --no-defaults --base64-output=decode-rows -vv "$dir/$f" | awk -v file="$f" -v pat="$pattern" '
    BEGIN { lpat = tolower(pat) }
    /^# at [0-9]+/ { pos = $3 }
    /^#[0-9][0-9][0-9][0-9][0-9][0-9] +[0-9]+:[0-9]+:[0-9]+/ {
      d = substr($1, 2); t = $2
      ts = "20" substr(d, 1, 2) "-" substr(d, 3, 2) "-" substr(d, 5, 2) " " t
    }
    /SET @@SESSION.GTID_NEXT= *'\''[^'\'']+'\''/ {
      g = $0; sub(/.*GTID_NEXT= *'\''/, "", g); sub(/'\''.*/, "", g); gtid = g; txpos = pos; txts = ts
    }
    index(tolower($0), lpat) > 0 && gtid != "" && !(gtid in seen) {
      seen[gtid] = 1
      line = $0; sub(/^### /, "", line)
      printf "%s  at %s  %s  GTID %s  %s\n", file, txpos, txts, gtid, substr(line, 1, 100)
    }
  ')"
  if [[ -n "$out" ]]; then
    echo "$out"
    found=1
  fi
done

if [[ "$found" -eq 0 ]]; then
  echo "没有找到包含 [$pattern] 的事件" >&2
  exit 1
fi
